// lib/gdpr.js
// ─────────────────────────────────────────────────────────────────────────────
// GDPR request letters (thesis §10.3–10.4, first step). Deliberately NOT
// generated by an LLM: a legal letter must say exactly what the law says, every
// time. The browser fills the template and the user sends it from their own
// mailbox — Exposio never contacts companies on anyone's behalf.
//
// Article references:
//   Art. 12(3)  answer within one month (extendable by two months, with reasons)
//   Art. 12(5)  free of charge
//   Art. 15     right of access; 15(1)(g) source of the data; 15(3) a copy
//   Art. 17     right to erasure; 17(3) the exemptions a company may rely on
//   Art. 19     tell recipients about the erasure
// ─────────────────────────────────────────────────────────────────────────────

export function gdprLetter(type, { company, email, year }) {
  const incident = year ? "the " + company + " data breach of " + year : "a data breach involving " + company;
  const who = email || "[your email address]";

  if (type === "erasure") {
    return [
      "Subject: Request for erasure of personal data — Article 17 GDPR",
      "",
      "Dear " + company + " Data Protection Officer,",
      "",
      "I am writing to request the erasure of all personal data you hold about me, under Article 17 of the General Data Protection Regulation (GDPR). My data appears to have been exposed in " + incident + ".",
      "",
      "The account or identifier concerned is: " + who,
      "",
      "Please:",
      "1. Erase my personal data without undue delay (Article 17(1)).",
      "2. Inform any recipients to whom my data was disclosed of this erasure (Article 19).",
      "3. If you believe an exemption under Article 17(3) applies to any of the data, tell me which data and which exemption.",
      "",
      "Please confirm in writing once the erasure is complete. Under Article 12(3) you must respond within one month of receiving this request. If you need to verify my identity, please tell me what you require.",
      "",
      "Kind regards,",
      "[your name]",
    ].join("\n");
  }

  return [
    "Subject: Data subject access request — Article 15 GDPR",
    "",
    "Dear " + company + " Data Protection Officer,",
    "",
    "Under Article 15 of the General Data Protection Regulation (GDPR), I request access to the personal data you hold about me. My data appears to have been exposed in " + incident + ".",
    "",
    "The account or identifier concerned is: " + who,
    "",
    "Please provide:",
    "1. Confirmation of whether you process my personal data, and a copy of it (Article 15(1) and 15(3)).",
    "2. The purposes of processing, the categories of data, and the recipients it was disclosed to.",
    "3. How long you will keep it, and where you obtained it if not from me (Article 15(1)(g)).",
    "4. Which of my data was affected by the breach, and what you have done about it.",
    "",
    "Under Article 12(3) you must respond within one month of receiving this request, and under Article 12(5) this must be free of charge. If you need to verify my identity, please tell me what you require.",
    "",
    "Kind regards,",
    "[your name]",
  ].join("\n");
}
